      es: ["Conectado con más de 600 puertos en 123 países.", "Segundo puerto de contenedores más grande del mundo por volumen.", "Ubicación importante para el abastecimiento de combustible de barcos."],
      pt: ["Ligado a mais de 600 portos em 123 países.", "Segundo maior porto de contentores do mundo por movimentação.", "Localização importante para o abastecimento de navios."],
