    description: {
      de: "Eines der größten Kraftwerke in Singapur, das eine entscheidende Rolle bei der Gewährleistung einer stabilen Stromversorgung für das Land spielt.",
      hu: "Szingapúr egyik legnagyobb erőműve, amely kulcsfontosságú szerepet játszik az ország stabil áramellátásának biztosításában.",
      ro: "Una dintre cele mai mari centrale electrice din Singapore, jucând un rol crucial în asigurarea unei surse stabile de energie electrică pentru țară.",
      en: "One of the largest power stations in Singapore, playing a crucial role in ensuring a stable electricity supply for the country.",
      es: "Una de las centrales eléctricas más grandes de Singapur, que desempeña un papel crucial para garantizar un suministro eléctrico estable para el país.",
      pt: "Uma das maiores centrais elétricas de Singapura, que desempenha um papel crucial para garantir um fornecimento elétrico estável para o país.",
      fr: "L'une des plus grandes centrales électriques de Singapour, jouant un rôle crucial dans la garantie d'un approvisionnement stable en électricité pour le pays.",
    },
    facts: {
      de: ["Verwendet hauptsächlich Erdgas als Brennstoff.", "Kombikraftwerk für höhere Effizienz.", "Kontinuierliche Modernisierung zur Reduzierung von Emissionen."],
      hu: ["Főként földgázt használ tüzelőanyagként.", "Kombinált ciklusú erőmű a nagyobb hatékonyság érdekében.", "Folyamatosan modernizálják a károsanyag-kibocsátás csökkentése érdekében."],
      ro: ["Utilizează în principal gaz natural drept combustibil.", "Centrală cu ciclu combinat pentru o eficiență sporită.", "Modernizată continuu pentru a reduce emisiile."],
      en: ["Primarily uses natural gas as fuel.", "Combined-cycle power plant for higher efficiency.", "Continuously upgraded to reduce emissions."],
      es: ["Utiliza principalmente gas natural como combustible.", "Central de ciclo combinado para mayor eficiencia.", "Modernización continua para reducir las emisiones."],
      pt: ["Utiliza principalmente gás natural como combustível.", "Central de ciclo combinado para maior eficiência.", "Modernização contínua para reduzir as emissões."],
      fr: ["Utilise principalement le gaz naturel comme combustible.", "Centrale à cycle combiné pour une efficacité accrue.", "Modernisation continue pour réduire les émissions."],
    }, image: "/poi-images/tuas-power-station-economic-v2.webp",
    descriptionAdvanced: {
      de: "Die Tuas Power Station ist eines der größten und effizientesten Kraftwerke in Singapur und spielt eine zentrale Rolle bei der Energieversorgung des Stadtstaates. Die im Westen der Insel gelegene Anlage hat eine installierte Gesamtkapazität von rund 2.670 Megawatt. Das Kraftwerk nutzt moderne Gas- und Dampfturbinen-Kombiprozesse (GuD), die Erdgas als primären Brennstoff verwenden, was die CO2-Emissionen im Vergleich zu Kohlekraftwerken deutlich reduziert. Tuas Power wurde in den 1990er Jahren in Betrieb genommen und war eines der ersten Kraftwerke, das im Zuge der Liberalisierung des Strommarktes privatisiert wurde. Die Anlage deckt etwa 20 % des gesamten Strombedarfs von Singapur. Neben der Stromerzeugung bietet das Unternehmen auch Energielösungen für Industriekunden im angrenzenden Industriegebiet Tuas an. Durch kontinuierliche technologische Upgrades wird die Effizienz der Stromerzeugung stetig verbessert, um die Nachhaltigkeitsziele Singapurs zu unterstützen.",
      hu: "A Tuas erőmű Szingapúr egyik legnagyobb és leghatékonyabb erőműve, amely központi szerepet játszik a városállam energiaellátásában. A sziget nyugati részén található létesítmény beépített összkapacitása megközelítőleg 2670 megawatt. Az erőmű modern kombinált ciklusú gáz- és gőzturbinákat (CCGT) használ, amelyek elsődleges tüzelőanyagként földgázt alkalmaznak, ezzel jelentősen csökkentve a szén-dioxid-kibocsátást a szénerőművekhez képest. A Tuas Power az 1990-es években kezdte meg működését, és az elsők között privatizálták a villamosenergia-piac liberalizációja során. A létesítmény Szingapúr teljes áramszükségletének körülbelül 20%-át fedezi. Az áramtermelés mellett a vállalat energiamegoldásokat is kínál a szomszédos Tuas ipari negyed ügyfelei számára. A folyamatos technológiai fejlesztések révén az erőmű hatékonysága állandóan javul, támogatva Szingapúr fenntarthatósági célkitűzéseit.",
      ro: "Centrala electrică Tuas este una dintre cele mai mari și eficiente unități de generare a energiei din Singapore, jucând un rol central în alimentarea statului. Situată în partea de vest a insulei, instalația are o capacitate instalată totală de aproximativ 2.670 megawați. Centrala utilizează procese moderne de turbine cu gaz cu ciclu combinat (CCGT), care folosesc gazul natural ca combustibil primar, reducând semnificativ emisiile de CO2 în comparație cu centralele pe cărbune. Tuas Power a fost dată în folosință în anii 1990 și a fost una dintre primele centrale privatizate în timpul liberalizării pieței de electricitate. Unitatea acoperă aproximativ 20% din cererea totală de energie a statului Singapore. Pe lângă producerea de electricitate, compania oferă soluții energetice pentru clienții industriali din zona adiacentă Tuas. Prin actualizări tehnologice continue, eficiența generării de energie este îmbunătățită constant pentru a susține obiectivele de sustenabilitate ale țării.",
      en: "Tuas Power Station is one of Singapore's largest and most efficient power generation facilities, playing a vital role in securing the nation's energy supply. Located on the western edge of the island, the plant has a total installed capacity of approximately 2,670 megawatts. It utilizes advanced Combined Cycle Gas Turbine (CCGT) technology, using natural gas as its primary fuel source, which significantly lowers carbon emissions compared to traditional coal-fired plants. Tuas Power commenced operations in the 1990s and was among the first generation of power plants to be privatized following the liberalization of Singapore's electricity market. The facility generates about 20% of the country's total electricity demand. Beyond power generation, it provides essential energy solutions and utilities to industrial customers in the surrounding Tuas industrial estate. Continuous technological upgrades ensure that the station remains at the forefront of efficiency and supports Singapore's long-term sustainability goals.",
    },
    factsAdvanced: {
      de: ["Installierte Gesamtkapazität von 2.670 Megawatt.", "Deckung von etwa 20 % des Strombedarfs von Singapur.", "Verwendung von Erdgas zur Reduzierung der CO2-Emissionen.", "Inbetriebnahme der ersten Kraftwerksblöcke in den 1990er Jahren.", "Betreibt fünf hocheffiziente Kombizyklus-Anlagen.", "Gehört heute zum Portfolio der China Huaneng Group."],
      hu: ["A beépített összkapacitás eléri a 2670 megawattot.", "Szingapúr áramszükségletének mintegy 20%-át biztosítja.", "Földgázalapú üzemeltetés a környezeti hatások minimalizálása érdekében.", "Az első egységek az 1990-es évek közepén kezdték meg a termelést.", "Öt darab nagy hatékonyságú kombinált ciklusú blokkot működtet.", "Jelenleg a China Huaneng Group tulajdonában áll."],
      ro: ["Capacitate totală instalată de 2.670 de megawați.", "Asigură aproximativ 20% din necesarul de energie al Singapore.", "Utilizează gaz natural pentru a minimiza emisiile de carbon.", "Operațiunile au început cu primele unități în anii 1990.", "Operează cinci unități moderne cu ciclu combinat de înaltă eficiență.", "Este deținută în prezent de corporația China Huaneng Group."],
      en: ["Features a total installed power capacity of 2,670 megawatts.", "Generates approximately 20% of Singapore's total electricity supply.", "Primarily fueled by natural gas to reduce the carbon footprint.", "The first power blocks were commissioned in the mid-1990s.", "Operates five highly efficient combined-cycle generation units.", "Currently a subsidiary owned by the China Huaneng Group."],
      es: [],
      pt: [],
      fr: [],
    },
