      ro: ["Întreaga zonă se întinde pe o suprafață de 200 de hectare.", "Planul general de dezvoltare a fost lansat oficial în anul 2001.", "Biopolis este hub-ul central pentru cercetarea în științe biologice.", "Găzduiește agenția de cercetare A*STAR și multe corporații globale.", "Conceptul arhitectural a fost creat de celebra Zaha Hadid.", "Deservit de două stații de metrou: one-north și Buona Vista."],
