    descriptionAdvanced: {
      de: "Der Tuas Mega Port ist ein gewaltiges Infrastrukturprojekt, das darauf abzielt, alle bestehenden Containerterminal-Operationen Singapurs an einem einzigen, hocheffizienten Standort zu bündeln. Die Phase 1 des Hafens wurde 2021 offiziell eröffnet und markiert den Beginn eines jahrzehntelangen Übergangs, der schließlich die Abfertigung von bis zu 65 Millionen TEU pro Jahr ermöglichen wird. Nach seiner Fertigstellung in den 2040er Jahren soll er das weltweit größte vollautomatisierte Containerterminal sein. Der Hafen nutzt modernste Technologien wie fahrerlose automatisierte Transportfahrzeuge (AGVs) und automatisierte Hofkräne, um Abläufe zu rationalisieren und Arbeitskosten zu senken. Diese hochmoderne Anlage wurde auf neugewonnenem Land errichtet und umfasst nachhaltige Merkmale wie grüne Gebäude und elektrifizierte Hafengeräte, um den CO2-Fußabdruck zu minimieren.",
      hu: "A Tuas Mega Port egy hatalmas infrastruktúra-projekt, amelynek célja Szingapúr összes meglévő konténerterminál-műveletének egyetlen, rendkívül hatékony helyszínen történő összevonása. A kikötő 1. fázisa hivatalosan 2021-ben nyílt meg, megkezdve azt a több évtizedes átmenetet, amelynek végén évente akár 65 millió TEU-t is kezelni fognak. A 2040-es évekre tervezett teljes befejezés után ez lesz a világ legnagyobb, teljesen automatizált konténerterminálja. A kikötő olyan élvonalbeli technológiákat alkalmaz, mint a vezető nélküli automata irányított járművek (AGV) és az automatizált udvari daruk a folyamatok racionalizálása érdekében. Ez a korszerű létesítmény feltöltött területen épült, és fenntartható megoldásokat tartalmaz, például zöld épületeket és elektromos kikötői berendezéseket a környezeti hatások minimalizálására.",
      ro: "Tuas Mega Port este un proiect masiv de infrastructură conceput pentru a consolida toate operațiunile terminalelor de containere existente din Singapore într-o singură locație extrem de eficientă. Faza 1 a portului s-a deschis oficial în 2021, marcând începutul unei tranziții de câteva decenii care va gestiona în cele din urmă până la 65 de milioane de TEU anual. Odată finalizat în anii 2040, acesta va deveni cel mai mare terminal de containere complet automatizat din lume. Portul utilizează tehnologie de ultimă oră, cum ar fi vehicule ghidate automate fără șofer (AGV) și macarale de curte automatizate, pentru a eficientiza operațiunile. Această unitate de ultimă generație este construită pe teren recuperat și încorporează caracteristici durabile, inclusiv clădiri verzi și echipamente portuare electrificate, pentru a minimiza amprenta de carbon.",
      en: "The Tuas Mega Port is a massive infrastructure project designed to consolidate all of Singapore's existing container terminal operations into a single, highly efficient location. Phase 1 of the port officially opened in 2021, marking the beginning of a multi-decade transition that will eventually handle up to 65 million TEUs annually. Once completed in the 2040s, it is set to become the world's largest fully automated container terminal. The port utilizes cutting-edge technology, such as driverless automated guided vehicles (AGVs) and automated yard cranes, to streamline operations and reduce labor costs. This state-of-the-art facility is built on reclaimed land and incorporates sustainable features, including green buildings and electrified port equipment, to minimize its carbon footprint while maximizing global connectivity.",
      es: "El Tuas Mega Port es un futuro superpuerto en el oeste de Singapur destinado a reemplazar los terminales de contenedores existentes. La primera fase entró en funcionamiento en 2022. Con una capacidad prevista de 65 millones de TEU al año, será uno de los puertos más grandes del mundo. Funcionará de forma totalmente automática con vehículos autónomos y sistemas de grúas inteligentes. Abarca una superficie de 1.300 ha y se completará en varias fases hasta 2040. Las inversiones superan los 20.000 millones de dólares, reforzando la posición de Singapur como centro marítimo global.",
      pt: "O Tuas Mega Port é um futuro superporto no oeste de Singapura destinado a substituir os terminais de contentores existentes. A primeira fase entrou em funcionamento em 2022. Com uma capacidade prevista de 65 milhões de TEU por ano, será um dos maiores portos do mundo. Funcionará de forma totalmente automática com veículos autónomos e sistemas de guindastes inteligentes. Abrange uma área de 1.300 ha e será concluído em várias fases até 2040. Os investimentos superam os 20 mil milhões de dólares, reforçando a posição de Singapura como centro marítimo global.",
      fr: "Le Tuas Mega Port est un futur super-port dans l'ouest de Singapour destiné à remplacer les terminaux à conteneurs existants. La première phase est entrée en service en 2022. Avec une capacité prévue de 65 millions d'EVP par an, il sera l'un des plus grands ports du monde. Il fonctionnera de manière entièrement automatique avec des véhicules autonomes et des systèmes de grues intelligents. Il couvre une superficie de 1 300 ha et sera achevé en plusieurs phases d'ici 2040. Les investissements dépassent les 20 milliards de dollars, renforçant la position de Singapour en tant que centre maritime mondial.",
    },
