    descriptionAdvanced: {
      de: "Die Shell-Raffinerie auf Pulau Bukom ist ein erstklassiger integrierter Chemie- und Energiepark und eines der bedeutendsten globalen Projekte von Shell. Der Betrieb der Raffinerie begann 1961, womit sie die erste Raffinerie Singapurs und ein Wegbereiter für die industrielle Entwicklung des Landes war. Über die Jahrzehnte hinweg ist sie zur größten Raffinerie im Alleineigentum von Shell weltweit gewachsen, die eine Vielzahl von Rohölsorten zu wichtigen Kraftstoffen und chemischen Rohstoffen verarbeitet. Die Anlage liegt auf einer Insel südlich der Hauptinsel Singapur und ist nahtlos in andere regionale Shell-Anlagen integriert. Sie spielt eine zentrale Rolle bei der Versorgung des asiatisch-pazifischen Raums mit Erdölprodukten und durchläuft derzeit eine Transformation hin zu kohlenstoffärmeren Energielösungen, einschließlich der Produktion von nachhaltigem Flugkraftstoff.",
      hu: "A Pulau Bukom szigetén található Shell finomító világszínvonalú integrált vegyipari és energiapark, a Shell egyik legjelentősebb globális eszköze. A finomító működése 1961-ben kezdődött, ezzel Szingapúr első finomítója és az ország ipari fejlődésének úttörője lett. Az évtizedek során a világ legnagyobb, teljes mértékben a Shell tulajdonában lévő finomítójává nőtte ki magát, amely a nyersolaj széles választékát dolgozza fel üzemanyagokká és vegyipari alapanyagokká. A Szingapúr főszigetétől délre fekvő szigeten elhelyezkedő létesítmény szervesen kapcsolódik a Shell többi regionális üzeméhez. Kulcsszerepet játszik az ázsiai-csendes-óceáni térség kőolajtermékekkel való ellátásában, és jelenleg az alacsonyabb szén-dioxid-kibocsátású megoldások felé alakul át, beleértve a fenntartható repülőgép-üzemanyag gyártását.",
      ro: "Rafinăria Shell de pe Pulau Bukom este un parc integrat de substanțe chimice și energie de clasă mondială și unul dintre cele mai importante active globale ale Shell. Operațiunile la rafinărie au început în 1961, devenind prima rafinărie din Singapore și un pionier în dezvoltarea industrială a națiunii. De-a lungul deceniilor, a crescut pentru a deveni cea mai mare rafinărie deținută integral de Shell din lume, procesând o varietate largă de țiței în combustibili esențiali. Situată pe o insulă la sud de insula principală Singapore, instalația este integrată perfect cu celelalte fabrici regionale ale Shell. Aceasta joacă un rol esențial în furnizarea de produse petroliere către regiunea Asia-Pacific și trece în prezent printr-o transformare către soluții energetice cu emisii reduse de carbon, inclusiv producția de combustibil durabil pentru aviație.",
      en: "The Shell refinery on Pulau Bukom is a world-class integrated chemicals and energy park and one of Shell's most significant global assets. Operations at the refinery first began in 1961, making it Singapore's first refinery and a pioneer in the nation's industrial development. Over the decades, it has grown to become Shell's largest wholly-owned refinery in the world, processing a wide variety of crude oil into essential fuels and chemical feedstocks. Located on an island just south of the main Singapore island, the facility is seamlessly integrated with Shell's other regional plants. It plays a pivotal role in the supply of petroleum products to the Asia-Pacific region and is currently undergoing a transformation toward lower-carbon energy solutions, including the production of sustainable aviation fuel.",
      es: "La refinería Shell Bukom, en la isla de Bukom, es una de las más grandes de Singapur. Desde 1961, procesa unos 500.000 barriles de crudo al día. La planta abarca más de 500 hectáreas y emplea a unas 3.000 personas. Produce gasolina, diésel, queroseno y materias primas petroquímicas. La refinería es un nodo central para el suministro energético regional. A pesar de las modernizaciones para reducir las emisiones, sigue siendo un factor económico significativo. Su ubicación estratégica en el estrecho de Malaca subraya su papel en el comercio mundial de petróleo.",
      pt: "A refinaria Shell Bukom, na ilha de Bukom, é uma das maiores de Singapura. Desde 1961, processa cerca de 500.000 barris de petróleo bruto por dia. A instalação abrange mais de 500 hectares e emprega cerca de 3.000 pessoas. Produz gasolina, gasóleo, querosene e matérias-primas petroquímicas. A refinaria é um centro fundamental para o fornecimento de energia regional. Apesar das modernizações para reduzir as emissões, continua a ser um fator económico significativo. A sua localização estratégica no Estreito de Malaca sublinha o seu papel no comércio mundial de petróleo.",
      fr: "La raffinerie Shell Bukom, sur l'île de Bukom, est l'une des plus grandes de Singapour. Depuis 1961, elle traite environ 500 000 barils de pétrole brut par jour. Le site couvre plus de 500 hectares et emploie environ 3 000 personnes. Il produit de l'essence, du diesel, du kérosène et des matières premières pétrochimiques. La raffinerie est un carrefour central pour l'approvisionnement énergétique régional. Malgré les modernisations visant à réduire les émissions, elle reste un facteur économique majeur. Son emplacement stratégique dans le détroit de Malacca souligne son rôle dans le commerce mondial du pétrole.",
    },
